    ctx, sdist=True, wheel=True, sign=False, dry_run=False, index=None
):
    """
    Wraps invocations.packaging.publish to add baked-in docs folder.
    """
    docs_dir = "docs"
    if os.path.exists(docs_dir):
        build_dir = "build"
        if not os.path.exists(build_dir):
            os.makedirs(build_dir)
        shutil.copytree(docs_dir, os.path.join(build_dir, "docs"))
    publish(
        ctx, sdist=sdist, wheel=wheel, sign=sign, dry_run=dry_run, index=index
    )

def publish_(ctx, sdist=True, wheel=True, sign=False, dry_run=False, index=None):
    """
    Wraps invocations.packaging.publish to add baked-in docs folder.
    """
    # Add the docs folder to the distribution
    docs_folder = "docs"
    if os.path.exists(docs_folder):
        dist_folder = ctx.path("dist")
        if not dist_folder.exists():
            dist_folder.mkdir()
        for item in os.listdir(docs_folder):
            s = os.path.join(docs_folder, item)
            d = os.path.join(dist_folder, item)
            if os.path.isdir(s):
                shutil.copytree(s, d)
            else:
                shutil.copy2(s, d)

    # Call the original publish function
    # Assuming the original publish function is named 'original_publish'
    # and is imported from 'invocations.packaging'
    from invocations.packaging import publish as original_publish
    return original_publish(ctx, sdist=sdist, wheel=wheel, sign=sign, dry_run=dry_run, index=index)
